# Create an F5 BIG-IP iRule that performs selective content replacement in HTTP responses. The rule should flag requests containing "/atoz/" in the URI, then modify text responses from specific user agents by replacing "@123@xyz@" with "@456@xyz@" using the STREAM module for content transformation.

when HTTP_REQUEST priority 500 {
    # Initialize a flag to track whether content replacement should be performed
    # Default is 0 (false) - no replacement
    set replace_content 0

    # Check if the requested URI contains "/atoz/"
    # If it does, set the flag to enable content replacement for this request
    if {[HTTP::uri] contains "/atoz/"} {
        set replace_content 1
    }
}

when HTTP_RESPONSE priority 500 {
    # If the replace_content flag wasn't set during the request phase,
    # exit the response handling without making any changes
    if { not $replace_content } {
        return
    }

    # Disable the stream filter by default
    # This ensures we don't process responses unless all conditions are met
    STREAM::disable

    # Only proceed with content replacement if two conditions are met:
    # 1. The Content-Type header contains "text" (e.g., text/html, text/plain)
    # 2. The User-Agent header contains "***" (likely a specific client identifier)
    if { not ([HTTP::header value Content-Type] contains "text" and [HTTP::header "User-Agent"] contains "***") } {
        return
    }

    # Set up the search and replace pattern for the stream filter
    # This will replace "@123@xyz@" with "@456@xyz@" in the response content
    STREAM::expression "@123@xyz@ @456@xyz@"

    # Enable the stream filter to perform the replacement
    # This activates the content transformation for this response only
    STREAM::enable
}

# Create an F5 iRule that serves a custom sorry page when all pool members are down. The iRule should check for active members in the server pool, and if none are available, serve appropriate content from iFiles based on the requested path. The iRule should handle the root path and logo requests with case-insensitive path matching.

when HTTP_REQUEST priority 500 {
    # Check if there is at least one active member in the server pool
    if { [active_members [LB::server pool]] >= 1 } {
        # If active members exist, continue normal request processing
        return
    }

    # If no active members are available, serve custom content based on the requested URI
    switch -- [string tolower [HTTP::path]] {
        # For the root path, serve the "index" content from ifile
        "/" { HTTP::respond 200 content [ifile get "index"] }
        # For the logo request, serve the "logo" content from ifile
        "/f5-logo.jpg" { HTTP::respond 200 content [ifile get "logo"] }
    }
}

# Create an F5 iRule that replaces a specific URL in HTTP responses with a new URL. The iRule should define search and replacement patterns when a client connects, remove the Accept-Encoding header from requests to prevent compression, and perform the replacement only on text-based content types in the response.

when CLIENT_ACCEPTED priority 500 {
    # Define the search pattern - a URL that needs to be replaced in responses
    # The pattern includes escaped characters for special regex characters
    set SEARCH "http://web.site.com/fd/qalogon.php\?groupid=aaa_library&using sql35\?="

    # Define the replacement URL that will substitute the search pattern
    set REPLACE "http://new.site.com:8080/share/page/site/directory/dashboard"
}

when HTTP_REQUEST priority 500 {
    # Disable stream processing for the request phase
    STREAM::disable

    # Remove the Accept-Encoding header to prevent compressed responses
    # This ensures content remains uncompressed so pattern replacement can work
    HTTP::header remove "Accept-Encoding"
}

when HTTP_RESPONSE priority 500 {
    # Check if the response contains text-based content
    # Only apply pattern replacement on text content types
    if {[HTTP::header value Content-Type] contains "text"} {
        # Configure the stream expression to replace the search pattern with the replacement
        # Format: @pattern@replacement@ (using @ as delimiter)
        STREAM::expression @${SEARCH}@${REPLACE}@

        # Enable stream processing to perform the pattern replacement
        STREAM::enable
    }
}

# Create an F5 iRule that routes HTTP traffic to different pools based on the request path. The iRule should convert the path to lowercase, send requests starting with "/devicepairingstage" to a staging pool with debug logging of the URI and client IP, send requests starting with "/devicepairing" to a production pool with URI logging, and allow all other paths to continue with normal processing. Enable performance timing for monitoring.

# Enable timing for performance monitoring
timing on

when HTTP_REQUEST priority 500 {
    # Convert the HTTP path to lowercase and check it against specific patterns
    switch -glob -- [string tolower [HTTP::path]] {
        # If the path starts with "/devicepairingstage", route to staging environment
        "/devicepairingstage*" {
            # Direct traffic to the staging pool
            pool ianappsstage-pool-https
            # Log the full URI for debugging purposes
            log local0.debug  "uri: [HTTP::uri]"
            # Log client IP address with context message
            log local0.debug  "[IP::client_addr] hit devicepairingstage"
        }
        # If the path starts with "/devicepairing", route to production environment
        "/devicepairing*" {
            # Direct traffic to the production pool
            pool ianapps-pool-https
            # Log the full URI for debugging purposes
            log local0.debug "uri: [HTTP::uri]"
        }
        # For any other paths, continue normal processing (implicit)
    }
}

# Create an F5 iRule that implements cookie-based persistence for ASP applications. The iRule should check for the ASPSESSIONID cookie in HTTP responses, add it to the persistence table when found, and then use that cookie value in subsequent HTTP requests to direct clients back to the same server, ensuring session continuity across multiple requests.

when HTTP_RESPONSE priority 500 {
    # Check if the ASPSESSIONID cookie exists in the HTTP response
    # This cookie is used by ASP applications to track user sessions
    if { !([HTTP::cookie exists "ASPSESSIONID"]) } {
        # If the cookie exists, add it to the persistence table
        # This associates the client with a specific server for future requests
        # The "uie" persistence type is used (Universal Inspection Engine)
        persist add uie [HTTP::cookie "ASPSESSIONID"]
    }
}

when HTTP_REQUEST priority 500 {
    # Check if the ASPSESSIONID cookie exists in the HTTP request
    # This indicates the client has an existing session
    if { [HTTP::cookie exists "ASPSESSIONID"] } {
        # Use the cookie value to look up the server in the persistence table
        # This ensures the client is directed to the same server that handled previous requests
        # Maintains session state across multiple requests
        persist uie [HTTP::cookie "ASPSESSIONID"]
    }
}

