# Create an F5 iRule that modifies file download behavior based on URL parameters. The iRule should capture the query string during the HTTP request, check for an "attachment=1" parameter, and modify the Content-Disposition response header by replacing "inline" with "attachment" when present, forcing browsers to download files instead of displaying them inline.

when HTTP_REQUEST priority 500 {
    # Capture the query string portion of the URI
    # This stores all parameters after the ? in the URL for later use
    set querystring [URI::query]
}

when HTTP_RESPONSE priority 500 {
    # Check if the previously stored query string contains "attachment=1" parameter
    # This parameter indicates the client wants the content as an attachment
    if { "$querystring" contains "attachment=1" } {
        # Modify the Content-Disposition header in the response
        # Replace any occurrence of "inline" with "attachment"
        # This forces the browser to download the content rather than display it inline
        # The -nocase flag makes the replacement case-insensitive
        HTTP::header replace Content-Disposition [string map -nocase "inline attachment" [HTTP::header Content-Disposition]]
    }
}

# Write an F5 iRule to Check if the combination of the host and URI from the HTTP request matches an entry in the /Common/redlist datagroup. If a match is found, update the Host header and URI with the new values provided in the match. If no match is found, do nothing.

when HTTP_REQUEST priority 500 {
    # Attempt to find a match in the /Common/redlist datagroup using the combination of the host and URI from the HTTP request.
    # If a match is found, the corresponding value (a string with three fields) is stored in the newURI variable.
    if { [set newURI [class match -value -- "[HTTP::host][HTTP::uri]" equals /Common/redlist]] eq "" } {
        # If no match is found (newURI is an empty string), return and do nothing.
        return
    }

    # Parse the newURI variable, which contains three fields separated by spaces. 
    # The fields are assigned to the variables 'unused', 'host', and 'uri' respectively.
    scan $newURI {%s %s %s} unused host uri

    # If the 'host' variable is not empty, replace the Host header in the HTTP request with the new value.
    if { $host ne "" } {
        HTTP::header replace Host $host
    }

    # If the 'uri' variable is not empty, replace the URI in the HTTP request with the new value.
    if { $uri ne "" } {
        HTTP::uri $uri
    }
}

