# Create an iRule for an F5 BIG-IP load balancer that handles HTTP requests with high priority. The rule should first check if the request path starts with "/xyz/" or if the query string contains "xy=9", ignoring case. If these conditions are met, it should handle WebSocket connections specially and route all such requests to "pool3". For other requests, it should route to "pool2" if the URI starts with "/fr/app", and to "pool1" for all other cases. Ensure all string comparisons are case-insensitive and the rule uses efficient control structures. The iRule should stop processing after routing to pool3. Write the iRule following F5 BIG-IP best practices, making it concise and efficient.

when HTTP_REQUEST priority 500 {
    # Check if the path starts with "/xyz/" (case-insensitive) or if the query contains "xy=9"
    if { ([string tolower [HTTP::path]] starts_with "/xyz/") || ([string tolower [HTTP::query]] contains "xy=9") } {
        # If the request is a GET method and contains a WebSocket upgrade header
        if { [HTTP::method] eq "GET" && [HTTP::header "Upgrade"] contains "WebSocket" } {
            # Disable HTTP processing for WebSocket connections
            HTTP::disable
        }
        # Route the request to pool3
        pool pool3
        # Exit the iRule processing
        return
    }

    # If the above conditions are not met, use a switch statement to route based on the URI
    switch -glob --[string tolower [HTTP::uri]] {
        # If the URI starts with "/fr/app" (case-insensitive), route to pool2
        "/fr/app*" { pool pool2 }
        # For all other URIs, route to pool1
        default    { pool pool1 }
    }
}

# Create an F5 BIG-IP iRule that provides a simple status page for a specific pool. The rule should run on HTTP requests, respond only to the "/status" path, and display whether the pool is up or down based on active members. Include the pool name, current member, port, and timestamp in the response.

when HTTP_REQUEST priority 500 {
    if {[HTTP::path] ne "/status" } {
        # If the requested Path is not "/status", exit the rule and continue normal processing
        return
    }

    # Parse the selected pool and member information
    scan [LB::select] %s%s%s%s%d command current_pool command2 current_member current_port
    # Re-select the pool member to ensure we're using the current selection
    eval {LB::select}

    # Start building the response with pool name and current timestamp
    set response "$current_pool Pool Status - [clock format [clock seconds]]http://[HTTP::host]/status'>"

    # Check if the pool has any active members
    if { [active_members $current_pool] < 1 } {
        # If no active members, report the pool as DOWN
        append response "POOL NAME:$current_pool CURRENT MEMBER:$current_member:$current_port STATUS: DOWN"
    } else {
        # If there are active members, report the pool as UP
        append response "POOL NAME:$current_pool CURRENT MEMBER:$current_member:$current_port STATUS: UP"
    }

    # Send an HTTP 200 response with the status information
    HTTP::respond 200 content $response "Content-Type" "text/html"
}

# Create an F5 BIG-IP iRule that routes POST requests to different pools based on an "idBiller" value in the request payload. It should collect the full payload for POST requests, decode it, extract the "idBiller" value, and use a switch statement to select the appropriate pool. If the "idBiller" is 11111111, route to Pool_XXX; otherwise, route to Pool_YYY.

when HTTP_REQUEST priority 500 {
    # Check if the HTTP method is POST
    if { ([HTTP::method] eq "POST") } {
        # If it's a POST request, collect the entire payload
        # The amount to collect is specified by the Content-Length header
        HTTP::collect [HTTP::header Content-Length]
    }
}

when HTTP_REQUEST_DATA priority 500 {
    # Decode the URL-encoded payload
    set decoded [URI::decode [HTTP::payload]]
    # Find the starting position of "idBiller" in the decoded payload
    set ini [string first "\"idBiller\"" $decoded]

    # If "idBiller" is not found, exit the rule
    if { $ini == -1 } {
        return
    }

    # Find the end of the "idBiller" value (marked by a comma)
    set end [string first "," $decoded $ini]
    # Extract the "idBiller" key-value pair
    set value [string range $decoded $ini [expr {$end-1}]]
    # Extract just the value part of "idBiller"
    set idBiller [lindex [split $value ":"] 1]

    # Use a switch statement to select the pool based on the idBiller value
    switch -exact -- $idBiller {
        11111111 {
            # If idBiller is 11111111, use Pool_XXX
            pool Pool_XXX
        }
        default {
            # For any other idBiller value, use Pool_YYY
            pool Pool_YYY
        }
    }
}

# Create an F5 BIG-IP iRule that routes HTTP requests to different pools based on the file extension of the requested resource. Route requests for image files (jpg, gif, png) to an image_pool, PDF files to a pdf_pool, and all other requests to a web_pool.

when HTTP_REQUEST priority 500 {
    # Use a switch statement with glob matching to check the requested path
    switch -glob -- [HTTP::path] {
        # For image file extensions (jpg, gif, png)
        "*.jpg"        -
        "*.gif"        -
        "*.png"        { pool image_pool }

        # For PDF files
        "*.pdf"        { pool pdf_pool }

        # For all other file types or paths
        default        { pool web_pool }
    }
}

# Create an F5 BIG-IP iRule that allows dynamic selection of a specific pool member based on a 'server' query parameter in the URI. If the `server` query parameter is not present, choose the default pool.

when CLIENT_ACCEPTED priority 500 {
    # Store the default pool for this virtual server
    set default_pool [LB::server pool]
}

when HTTP_REQUEST priority 500 {
    # Extract the 'server' parameter from the URI query string
    set target_member [URI::query [HTTP::uri] server]

    # If no 'server' parameter is found, exit the rule
    if { ($target_member eq "") } {
        return
    }

    # Select the specific pool member based on the 'server' parameter
    pool $default_pool member $target_member

    # Remove the 'server' parameter from the URI to hide it from the backend server
    HTTP::uri [string map -nocase [list "&server=$target_member" "" ] [HTTP::uri]]
}

# Create an F5 BIG-IP iRule that dynamically selects different SNAT pools based on destination server addresses and client IP addresses. The rule should check the selected server's IP address, then examine the client's IP address to determine the appropriate SNAT pool, with special handling for a specific test client and fallback to automap for unspecified servers.

when LB_SELECTED priority 500 {
    # This event triggers after a server has been selected for load balancing
    # but before the connection is established

    # Outer switch statement: Select SNAT behavior based on destination server address
    switch -- [LB::server addr] {
        222.35.42.126 {
            # For connections to server 222.35.42.126
            # Inner switch: Further refine SNAT selection based on client IP
            switch -- [IP::client_addr] {
                192.168.3.11 {
                    # For specific client 192.168.3.11 connecting to CRT server
                    # Use a special test SNAT pool
                    snatpool snat_crt_test2
                }
                default {
                    # For all other clients connecting to CRT server
                    # Use the standard CRT SNAT pool
                    snatpool snat_crt_pool
                }
            }
        }
        221.218.248.155 {
            # For connections to server 221.218.248.155 (likely a UNI server)
            # Inner switch: Further refine SNAT selection based on client IP
            switch -- [IP::client_addr] {
                192.168.3.11 {
                    # For specific client 192.168.3.11 connecting to UNI server
                    # Use a special test SNAT pool
                    snatpool snat_uni_test2
                }
                default {
                    # For all other clients connecting to UNI server
                    # Use the standard UNI SNAT pool
                    snatpool snat_uni_pool
                }
            }
        }
        default {
            # For connections to any other server not specifically listed
            # Use SNAT automap (uses self-IP addresses for translation)
            snat automap
        }
    }
}

# Create an F5 BIG-IP iRule that applies snat based on the client's IP subnet. The rule should assign specific SNAT addresses (1.1.1.1, 2.2.2.2, or 3.3.3.3) to clients from different /26 subnets within the 10.9.9.0 network, while allowing all other clients to use the default routing without SNAT.

when CLIENT_ACCEPTED priority 500 {
    # This event triggers when a client connection is first established

    # Check if client IP is in the 10.9.9.0/26 subnet (10.9.9.0 - 10.9.9.63)
    # and apply SNAT using the 1.1.1.1 address for these clients
    if { [IP::addr [IP::client_addr] equals 10.9.9.0/26] } {
        snat 1.1.1.1
        return
    }

    # Check if client IP is in the 10.9.9.65/26 subnet (10.9.9.64 - 10.9.9.127)
    # and apply SNAT using the 2.2.2.2 address for these clients
    if { [IP::addr [IP::client_addr] equals 10.9.9.65/26] } {
        snat 2.2.2.2
        return
    }

    # Check if client IP is in the 10.9.9.128/26 subnet (10.9.9.128 - 10.9.9.191)
    # and apply SNAT using the 3.3.3.3 address for these clients
    if { [IP::addr [IP::client_addr] equals 10.9.9.128/26] } {
        snat 3.3.3.3
        return
    }

    # For all other client IP addresses not matching the above subnets,
    # use the default routing without applying SNAT
    forward
}

# Create an F5 iRule that randomizes SNAT IP selection from a predefined class. The iRule should build a list of available SNAT IPs from CIDR blocks in a class called snat_class during initialization, and assign a random SNAT IP to each client connection.

# Convert an IP address in dotted decimal format to an integer
proc ip2int { ip } {
    set octets [split $ip .]
    set ipint [expr {(256 * 256 * 256 * [lindex $octets 0]) + (256 * 256 * [lindex $octets 1]) + (256 * [lindex $octets 2]) + [lindex $octets 3]}]
    return $ipint
}

# Generate a random integer between 0 and max (inclusive)
proc random { max } {
    return [expr {int(rand()*($max+1))}]
}

# Initialize the SNAT pool when the rule is loaded
when RULE_INIT priority 500 {
    # Create an empty list to store all available SNAT IP addresses
    set static::snat_list {}

    # Iterate through each CIDR entry in the snat_class
    foreach elm [class get snat_class] {
        # Parse the CIDR notation into IP and subnet mask
        scan [lindex $elm 0] {%[^/]/%s} ip mask

        # Get the subnet address
        set st [IP::addr $ip mask $mask]

        # Calculate the number of IP addresses in this subnet
        set num [expr {[call ip2int 255.255.255.255] - [call ip2int $mask] + 1}]

        # Add each IP address in the subnet to the SNAT list
        for {set i 0} {$i < $num} {incr i} {
            set t [expr {[call ip2int $ip] + $i}]
            lappend static::snat_list [IP::addr parse -ipv4 [binary format I $t]]
        }
    }

    # Store the total number of available SNAT IP addresses
    set static::snat_len [llength $static::snat_list]

    # Clean up temporary variables
    unset -nocomplain -- elm ip mask st num i t
}

# When a client connection is accepted, assign a random SNAT IP
when CLIENT_ACCEPTED priority 500 {
    # Select a random IP from the SNAT list and apply it as the source address
    snat [lindex $static::snat_list [call random $static::snat_len]]
}

# Create an F5 iRule that routes HTTP requests to specific backend nodes based on URI content. The iRule should use case-insensitive pattern matching to check if the URI contains "hypplanning" or "drmservice", and direct matching requests to the appropriate node with specific IP addresses, interfaces, and ports.

when HTTP_REQUEST priority 500 {
    # This event triggers when an HTTP request is received

    # Use switch with glob pattern matching to examine the lowercase URI
    # -glob enables wildcard matching with * to match any characters
    # -- marks the end of switch options
    # [string tolower [HTTP::uri]] converts the URI to lowercase for case-insensitive matching
    switch -glob -- [string tolower [HTTP::uri]] {
        # If the URI contains "hypplanning" anywhere in the path
        # Example: "/path/to/hypplanning/resource" or "?param=hypplanning"
        "*hypplanning*" {
            # Route this request to a specific backend node with IP 10.x.x.x on interface x and port x
            # The %x syntax specifies which network interface to use (route domain)
            node 10.x.x.x%x:x
        }
        # If the URI contains "drmservice" anywhere in the path
        # Example: "/path/to/drmservice/resource" or "?param=drmservice"
        "*drmservice*" {
            # Route this request to a different backend node with IP 10.x.x.x on interface x and port y
            node 10.x.x.x%x:y
        }
        # Implicit default case: if none of the patterns match, 
        # the request continues to the default pool or next iRule
    }
}

