            # Redirect all Netherlands domain requests to the EU domain with NL-specific path
            HTTP::respond 301 Location "http://www.mydomain.eu/nl/zz/index.jsp" 
        }
        "www.mydomain.fr" -
        "mydomain.fr" { 
