    # Extract the hostname without the port using getfield (splits at ":" and takes first part)
    # Combine with the original URI path to preserve the requested resource
    # Redirect the client to the same URL but without the port number, using HTTPS
    HTTP::redirect "https://[getfield [HTTP::host] ":" 1][HTTP::uri]"
}

# Create an F5 BIG-IP iRule that removes port numbers from redirect URLs for a specific domain. Check if the response is a redirect containing a specific domain with port number, log the original URL, remove the port number, and log the modified URL.

when HTTP_RESPONSE priority 500 {
    # Check if the response is not a redirect (3xx status code)
    # If it's not a redirect, exit the rule without taking any action
    if { ![HTTP::is_redirect] } {
        return
    }

    # Check if the Location header does not contain "www.acme.com:10040"
    # If it doesn't contain this specific domain and port, exit the rule
    if { !([HTTP::header Location] contains "www.acme.com:10040") } {
        return
    }

    # Log the original Location header value for debugging purposes
    log local0. "Original Location value: [HTTP::header Location]"

    # Replace the Location header value, removing the port number (10400)
    # This converts "www.acme.com:10400" to just "www.acme.com" in the redirect URL
    HTTP::header replace Location [string map -nocase {www.acme.com:10400 www.acme.com} [HTTP::header value Location]]
}

when HTTP_RESPONSE priority 501 {
    # Secondary event handler with slightly lower priority (501)
    # Check if the response is not a redirect
    if { ![HTTP::is_redirect] } {
        return
    }

    # Debug logging only. Remove this event once done testing
    # This logs the final Location header value after any modifications from the priority 500 handler
    log local0. "Updated Location value: [HTTP::header Location]"
}

# Create an F5 BIG-IP iRule that implements round-robin redirection between two servers. The rule should alternate between redirecting requests to Server1 and Server2.

when CLIENT_ACCEPTED priority 500 {
    # Initialize a counter variable to track which server to redirect to
    # Starting with 0 means the first request will go to Server1
    set whichone 0
}

when HTTP_REQUEST priority 500 {
    # Use a switch statement to alternate between servers
    switch -- $whichone {
        0 {
            # When counter is 0, redirect to Server1
            HTTP::redirect "http://Server1/blah"
            # Update counter for the next request
            set whichone 1
        }
        default {
            # For any other value (which will be 1), redirect to Server2
            HTTP::redirect "http://Server2/blah"
            # Reset counter back to 0 for the next request
            set whichone 0
        }
    }
}

# Create an F5 BIG-IP iRule that selectively enforces HTTPS for specific URI patterns. The rule should only process requests on port 80, log connection information, check if the requested URI matches patterns in a "secure_uris" data group, and redirect matching requests to HTTPS while allowing non-matching URIs to continue using HTTP.

when HTTP_REQUEST priority 500 {
    # Only process requests coming in on port 80 (HTTP)
    # Skip processing for other ports (like 443/HTTPS)
    if { [TCP::local_port] != 80 } {
        return
    }

    # Log that a connection is being made via HTTP for troubleshooting
    log local0. "connecting on HTTP server"

    # Check if the requested URI matches any patterns in the "secure_uris" data group
    # This data group contains paths that should be accessed securely
    if { [class match -- [HTTP::uri] starts_with /Common/secure_uris] } {
        # Redirect matching requests to HTTPS (note: there appears to be a typo here - 
        # the redirect is to "http://" not "https://", which would not enforce HTTPS)
        # This should likely be "https://" to properly redirect to secure protocol
        HTTP::redirect "http://[HTTP::host][HTTP::uri]"
    }
    # Non-matching URIs are allowed to continue using HTTP
}

# Create an F5 iRule that handles HTTP requests differently based on source IP. For clients in the 10.110.10.0/24 subnet, allow normal processing. For all other clients, replace the Host header with "www.abc.com" and redirect to "/go" unless the URI already starts with "/go".

when HTTP_REQUEST priority 500 {
    # Check if the client IP address is in the 10.110.10.0/24 subnet
    if { [IP::addr [IP::client_addr] equals 10.110.10.0/24] } {
        # For internal clients in this subnet, use default routing with no modifications
        # Exit the iRule to allow normal request processing
        return
    }

    # For all other client IPs (external clients), modify the request

    # Replace the Host header with "www.abc.com" regardless of what was sent
    HTTP::header replace Host "www.abc.com"

    # Check if the URI starts with "/go"
    if { [string tolower [HTTP::uri]] starts_with "/go"} {
        # Exit the iRule to allow normal request processing
        return
    }

    # If it doesn't start with "/go", replace the entire URI with just "/go"
    HTTP::uri "/go"
}

# Create an F5 iRule that redirects HTTP requests to HTTPS except for specific alumni paths. The iRule should convert the URI to lowercase and allow HTTP access for any paths containing "*alumni/giving/gift/", "*alumni/giving/pledge/", "*alumni/directory/search.aspx", or "*alumni/directory/update.aspx" using glob pattern matching. All other paths should receive a 301 redirect to the same hostname and URI but with HTTPS protocol.

when HTTP_REQUEST priority 500 {
    # Convert the URI to lowercase and check it against specific patterns
    switch -glob -- [string tolower [HTTP::uri]] {
        "*alumni/giving/gift/" -
        "*alumni/giving/pledge/" -
        "*alumni/directory/search.aspx" -
        "*alumni/directory/update.aspx" {
            # Don't redirect these paths - allow them to continue as HTTP
        }
        default {
            # Redirect to HTTPS while preserving the hostname and URI
            # getfield extracts the hostname without the port number
            HTTP::respond 301 Location "https://[getfield [HTTP::host] : 1][HTTP::uri]"
        }
    }
}

# Create an F5 iRule that rewrites specific case sensitive portal URIs to a standardized backend path. The iRule should match requests to "/app/DentegraPortal/TransEDI", "/app/DeltaCarePortal/TransEDI", "/app/B2BEnt/TransEDI", and "/app/B2BPMI/TransEDI", log the original URI, and rewrite all of them to "/b2b/transportServlet/TransEDI".

when HTTP_REQUEST priority 500 {
    # Use switch statement to match the incoming URI against specific patterns
    # The -- argument indicates the end of switch options and the start of the pattern to match
    switch -- [HTTP::uri] {
        "/app/DentegraPortal/TransEDI" -
        "/app/DeltaCarePortal/TransEDI" -
        "/app/B2BEnt/TransEDI" -
        "/app/B2BPMI/TransEDI" {
            # Log the original URI before rewriting for troubleshooting purposes
            log "Incoming uri - [HTTP::uri] being translated to /b2b/transportServlet/TransEDI"

            # Rewrite the URI to the standardized backend endpoint
            # This allows multiple frontend paths to be consolidated to a single backend path
            HTTP::uri "/b2b/transportServlet/TransEDI"
        }
        # Implicit default case: if none of the patterns match, no action is taken and the URI remains unchanged
    }
}

# Create an F5 iRule that rewrites URIs based on backend server selection. The iRule should only process requests going to specific servers (10.64.225.101-103), check the normalized URI path for patterns like "/gsfo/gsfopub" or "/era/erapub", and rewrite matching URIs to standardized endpoints ("/Async/CMReceive.ashx" or "/Async/ERAReceive.ashx" respectively). Include detailed logging for troubleshooting.

when HTTP_REQUEST_SEND priority 500 {
    # Convert the client-side URI to lowercase for case-insensitive matching
    # Using clientside command to access the client's original HTTP request
    set uri [string tolower [clientside {HTTP::uri -normalized}]]

    # Log the client IP:port, selected server details, and the URI for troubleshooting
    # This creates a record of which backend server was selected for each request
    log local0. "[set client_ip_port [IP::client_addr]:[TCP::client_port]]: selected server details: [LB::server] - \: $uri"

    # Only proceed with URI rewriting for specific backend servers (101, 102, 103)
    # Skip URI rewriting for all other backend servers
    if { ![IP::addr [LB::server addr] equals 10.64.225.101]
      && ![IP::addr [LB::server addr] equals 10.64.225.102]
      && ![IP::addr [LB::server addr] equals 10.64.225.103] } {
        return
    }

    # Log that the server IP matched one of our target servers
    log local0. "${client_ip_port}: matched server check for .3 or .4"

    # Use switch with glob pattern matching to check the normalized URI path
    # -glob enables wildcard matching, and -normalized ensures consistent path format
    switch -glob -- [string tolower [HTTP::uri -normalized]] {
        # If URI contains "/gsfo/gsfopub" anywhere in the path
        # Example: "/some/path/gsfo/gsfopub/endpoint"
        "*/gsfo/gsfopub*" {
            # Rewrite the client-side URI to a specific endpoint
            # This standardizes various GSFO requests to a single backend endpoint
            clientside {HTTP::uri "/Async/CMReceive.ashx"}
            # Log the URI rewriting action for troubleshooting
            log local0. "${client_ip_port}: updated URI to /Async/CMReceive.ashx"
        }
        # If URI contains "/era/erapub" anywhere in the path
        # Example: "/some/path/era/erapub/endpoint"
        "*/era/erapub*" {
            # Rewrite the client-side URI to a different specific endpoint
            # This standardizes various ERA requests to a single backend endpoint
            clientside {HTTP::uri "/Async/ERAReceive.ashx"}
            # Log the URI rewriting action for troubleshooting
            log local0. "${client_ip_port}: updated URI to /Async/ERAReceive.ashx"
        }
        # Default case: if URI doesn't match any of the patterns above
        default {
            # Log that no URI rewriting was performed
            log local0. "${client_ip_port}: didn't match URI checks"
        }
    }
}

# Create an F5 iRule that removes session IDs from static resource URLs. The iRule should check if the requested path is for a static resource (gif, js, css, jpg, or bmp file), extract the session ID and the rest of the URI, and then rewrite the URI to remove the session ID portion, preserving only the actual resource path.

when HTTP_REQUEST priority 500 {
    # Check the requested path (URI minus query string)
    switch -glob -- [string tolower [HTTP::path]] {
        "*.gif" -
        "*.js" -
        "*.css" -
        "*.jpg" -
        "*.bmp" {
            # Read in everything after the first / that is not a /.
            # Save that to $session_id and everything else to $uri_to_save
            # scan will return the number of matches
            if { [scan [HTTP::uri] {/%[^/]%s} session_id uri_to_save] == 2 } {
                # Rewrite the URI without the session ID
                #log local0. "$session_id"
                HTTP::uri $uri_to_save
            }
        }
    }
}

# Explain the differences between 301 redirects, 302 redirects, and VIP-to-VIP routing in F5 iRules, including when each should be used, how they affect client experience.

# 302 Redirect
ltm rule redirect_302 {
    when HTTP_REQUEST priority 500 {
        # This event triggers when an HTTP request is received

        if { ...some condition... } {
            # When the specified condition is met, perform a temporary redirect
            # HTTP 302 is a temporary redirect that tells clients the resource
            # has been temporarily moved to a different URL
            # Browsers typically don't update bookmarks for 302 redirects
            HTTP::redirect "https://somewhere.else.com"
        }
    }
}

# 301 Redirect
ltm rule redirect_301 {
    when HTTP_REQUEST priority 500 {
        # This event triggers when an HTTP request is received

        if { ...some condition... } {
            # When the specified condition is met, perform a permanent redirect
            # HTTP 301 is a permanent redirect that tells clients the resource
            # has been permanently moved to a different URL
            # Browsers typically update bookmarks for 301 redirects
            # Search engines transfer link equity to the new URL
            HTTP::respond 301 Location "https://somewhere.else.com"
        }
    }
}

# Vip-to-Vip direct
ltm rule redirect_vip {
    when HTTP_REQUEST priority 500 {
        # This event triggers when an HTTP request is received

        if { ...some condition... } {
            # When the specified condition is met, internally route the request
            # to another virtual server without client redirection
            # This is an internal traffic steering mechanism that is transparent to the client
            # The client's URL doesn't change, only the backend processing changes
            virtual internal-vs
        }
    }
}

# Create an F5 iRule that implements geolocation-based access control. The iRule should identify the client's country using the whereis command, log connection attempts with their country of origin, allow connections from the US and Canada, silently drop connections from Great Britain, and reset connections from all other countries.

when FLOW_INIT priority 500 {
    # Get the client's IP address and store it in the variable "ipaddr"
    set ipaddr [IP::client_addr]

    # Use the "whereis" command to determine the country of origin for the IP address
    # This requires the F5 geolocation database to be properly configured
    set locale [whereis $ipaddr country]

    # Log the client IP address and country code to the local0 facility
    # This creates an audit trail of connection attempts and their origins
    log local0. "IP Address/Counry $ipaddr/$locale"

    switch -- $locale {
        "US" -
        "CA" { 
            # Allow connections from the United States and Canada
            # The return command allows the connection to proceed normally
            return 
        }
        "GB" { 
            # Drop connections from Great Britain
            # ACL::action drop silently terminates the connection without notification
            ACL::action drop 
        }
        default { 
            # For all other countries
            # ACL::action reset terminates the connection and sends a TCP reset
            # This actively notifies the client that the connection was refused
            ACL::action reset 
        }
    }
}

# Create an F5 iRule that blocks access to specific URLs defined in a data group while allowing exceptions. The iRule should check if the URI contains any string from a "subsite" data group, exclude requests to the admin upload path, verify the client IP is not in an allowed IP list, and return a custom 200 response with a "Forbidden" message when access should be blocked.

when HTTP_REQUEST priority 500 {
    # Check three conditions to determine if access should be blocked:
    # 1. Check if the normalized, lowercase URI contains any string in the "subsite" data group
    # 2. Ensure the URI does not contain the admin upload path (which is allowed)
    # 3. Verify the client IP is not in the "allow" data group of permitted IPs
    if { ([class match -- [string tolower [HTTP::uri -normalized]] contains /Common/subsite])
     && !([string tolower [HTTP::uri]] contains "/admin/upload")
     && ![class match -- [IP::addr [IP::client_addr]] eq allow] } {
            # If all conditions are met (URI is restricted, not the upload path, and IP not allowed)
            # Return a 200 response with a custom error message
            # The "noserver" option prevents sending the F5 server header
            HTTP::respond 200 content "Forbidden Redirect From Remote Server\Acess is forbidden" noserver
    }
}

when CLIENT_ACCEPTED priority 500 {
  set BLOCKLIST_REPLY_IPV4 "10.110.10.10"
  set BLOCKLIST_TTL "100"
}
when DNS_REQUEST priority 500 {
  set Blocklist_Match 0
  set Blocklist_Type ""
  set domain_name [DNS::question name]
  if { [DNS::header "rd"] == 1 } {
    if { not [class match -- [IP::client_addr] eq "admin_datagroup" ] } {
      DNS::drop
    } elseif { [string tolower [class match -- $domain_name eq Blocklist_Class]] } {
      set Blocklist_Match 1
      DNS::return
    }
  }
}
when DNS_RESPONSE priority 500 {
  if { $Blocklist_Match } {
    switch -- [DNS::question type] {
      "A" {
        DNS::answer clear
        DNS::answer insert "[DNS::question name]. $BLOCKLIST_TTL [DNS::question class] [DNS::question type] $BLOCKLIST_REPLY_IPV4"
        DNS::header ra "1"
      }
      default {
        DNS::last_act reject
      }
    }
  }
}

when CLIENT_DATA priority 500 {
  binary scan [UDP::payload] x240H* dhcp_option_payload
  set option 0
  set option_length [expr {([UDP::payload length] -240) * 2 }]
  for {set i 0} {$option != 52 && $i < $option_length} {incr i [expr { $length * 2 +2 }]} {
    binary scan $dhcp_option_payload x[expr {$i}]a2 option
    incr i 2
    binary scan $dhcp_option_payload x[expr {$i}]a2 length_hex
    set length [expr {0x$length_hex}]
  }
  if { $i < $option_length } {
    incr i -[expr { $length * 2 -2 }]
    binary scan $dhcp_option_payload x[expr {$i}]a2 length_hex
    set length [expr {0x$length_hex}]
    incr i 2
    binary scan $dhcp_option_payload x[expr {$i}]a[expr { $length * 2 }] circuit_id
  } else {
    drop
  }
}

when HTTP_REQUEST priority 500 {
  binary scan [md5 [set http_password [HTTP::password]]] H* password
  if { [class lookup [set http_username [HTTP::username]] /Common/authorized_users] equals $password } {
    log local0. "User ${http_username} has been authorized to access virtual server [virtual name]"
    # Insert iRule-based application code here if necessary
  } else {
      if { [string length ${http_password}] != 0 } {
        log local0. "User ${http_username} has been denied access to virtual server [virtual name]"
      }
      HTTP::respond 401 WWW-Authenticate "Basic realm=\"Secured Area\""
  }
}

when CLIENT_ACCEPTED priority 500 {
    if { ([TCP::local_port] >= 8000) && ([TCP::local_port] <= 8020) } {
        pool mypool_[TCP::local_port]
    } else {
        drop
    }
}

when CLIENT_ACCEPTED priority 1 {
    if { [class match -- [IP::client_addr] equals allow_list] } {
        log local0. "client: [IP::client_addr] found in allow_list directed to http_test_pool"
        pool http_test_pool
        event disable all
    }  elseif { [class match -- [IP::client_addr] equals deny_list] } {
        log local0. " client: [IP::client_addr] found in deny_list directed to http_test_pool_2"
        pool http_test_pool_2
        # or discard
        event disable all
    }
}

# Write an F5 iRule that filters HTTP requests based on URI and client IP. The rule should allow requests only if the URI is in an approved list and the client IP is authorized. Use data groups for the allowed URIs and IPs. Drop any request that doesn't meet both criteria. Keep the code concise and include basic comments.

when HTTP_REQUEST priority 500 {
    # Check if the lowercase URI matches any entry in the "Allowed-URIs" data group
    if { ![class match -- [string tolower [HTTP::uri]] eq "Allowed-URIs"] } {
        # If URI is not in the allowed list, exit the iRule without taking action
        return
    }

    # Check if the client's IP address matches any entry in the "Allowed-IPs" data group
    if { [class match -- [IP::client_addr] eq "Allowed-IPs"] } {
        # If client IP is in the allowed list, exit the iRule without taking action
        # This allows the request to proceed normally
        return
    }

    # If we reach this point, it means:
    # 1. The URI is in the allowed list
    # 2. But the client IP is not in the allowed list
    # Therefore, we drop the request
    drop
}

# Create an F5 BIG-IP iRule that controls access to intranet pages. The rule should allow internal IP addresses to access all pages. For external IP addresses, it should check if they're trying to access specific intranet pages by examining the URL. If an external IP tries to access a protected intranet page, the request should be dropped and logged. Otherwise, allow the request to proceed.

when HTTP_REQUEST priority 500 {
    # Check if the client's IP address is in the InternalIPs class
    if { ([class match -- [IP::client_addr] equals /Common/InternalIPs]) } {
        # If it's an internal IP, allow the request to proceed normally
        return
    }

    # Decode the URI, convert to lowercase, and try to extract the tabid parameter
    if {[scan [string tolower [HTTP::uri -normalized]] "/default.aspx?tabid=%d" tabid] != 1 } {
        # If the URI doesn't match the expected format, allow the request to proceed
        return
    }

    # Check if the extracted tabid is in the intranet_pages class
    if { ![class match -- ${tabid} equals /Common/intranet_pages] } {
        # If the tabid is not in the intranet_pages class, allow the request to proceed
        return
    }

    # If we've reached this point, it means:
    # 1. The request is from an external IP
    # 2. The URI matches the format for accessing an intranet page
    # 3. The requested page (tabid) is in the intranet_pages class
    # Therefore, we drop the request to prevent external access to intranet pages
    drop
    # Log the dropped request with the client's IP address
    log local0. "Dropped request from IP:  [IP::client_addr]"
}

# Create an F5 BIG-IP iRule to detect and prevent potential path traversal attacks in HTTP requests. The rule should check the query string for suspicious patterns, log details of potential attacks for debugging purposes, and reject any requests that appear to be attempting path traversal. Include a debug flag that can be easily enabled or disabled.

when CLIENT_ACCEPTED priority 500 {
    # Initialize DEBUG variable to 1 (true) for logging purposes
    set DEBUG 1
}

when HTTP_REQUEST priority 500 {
    # Check if the query string contains potential path traversal attempts
    # The regex looks for '..' or '/' followed by any combination of alphanumeric characters, dots, or slashes
    if { [HTTP::query] matches_regex {^.*=(\.\.|/)[[A-Za-z0-9./]*]*.*$} } {
        # If DEBUG is enabled, log the client IP and the normalized URI
        if { ${DEBUG} } { 
            log local0. "Triggered by IP [IP::client_addr] with URI [HTTP::uri -normalized]" 
        }
        # Reject the request if a potential path traversal is detected
        reject
    }
}

# Create an F5 BIG-IP iRule that implements referrer-based access control for your website content. The rule should check the Referer header of incoming HTTP requests and handle them differently based on the source. Allow requests from specific approved websites to proceed normally. For requests with empty Referer headers, return an empty 200 OK response and log the client's IP address. For requests from any other referrers, redirect the client back to the site they came from and log both the blocked referrer and client IP address.

when HTTP_REQUEST priority 500 {
    # Extract the hostname from the Referer header and convert to lowercase for case-insensitive matching
    switch -glob -- [string tolower [URI::host [HTTP::header "Referer"]]] {
        "www.mywebsite.com" -
        "www.contentwebsite.com" {
            # Allow requests from approved referrers to proceed normally
            # No action needed here as the request will continue through the normal flow
        }
        "" {
            # Handle requests with empty/blank Referer headers
            # Return an empty 200 OK response to prevent further processing
            HTTP::respond 200 content ""
            # Log the event with the client's IP address
            log local0 "Blank Referer from IP: [IP::client_addr]"
        }
        default {
            # Handle requests from any other referrers (not in the approved list)
            # Redirect the client back to the site they came from
            HTTP::redirect [HTTP::header "Referer"]
            # Log the blocked referrer and the client's IP address
            log local0 "Blocked Referer: [HTTP::header value Referer] from IP: [IP::client_addr]"
        }
    }
}

# Create an F5 BIG-IP iRule that restricts access to specific URI paths based on client IP addresses. The rule should use pattern matching to identify different URI paths and check if the client's IP address belongs to the appropriate data groups for each path, returning a 403 Forbidden response for unauthorized access attempts while allowing all other requests to proceed normally.

when HTTP_REQUEST priority 500 {
    # Use a switch statement to match the requested URI against different patterns
    # The -glob flag enables glob-style pattern matching (wildcards)
    switch -glob -- [HTTP::uri] {
        # Match any URI that starts with "/error"
        "/error*" {
            # Check if the client's IP address belongs to either ipgrouptest or ipgrouptest2 data groups
            # These data groups contain allowed IP addresses for this URI pattern
            if { (([class match -- [IP::client_addr] equals ipgrouptest]) or ([class match -- [IP::client_addr] equals ipgrouptest2])) } {
                # If the client IP matches either allowed group, do nothing and allow the request to proceed
                # The request continues through the normal processing flow
            } else {
                # If the client IP doesn't match any allowed group, block access
                # Return HTTP 403 Forbidden response and terminate request processing
                HTTP::respond 403
            }
        }
        # Match any URI that starts with "/example"
        "/example*" {
            # Check if the client's IP address belongs to either ipgrouptest or ipgrouptest3 data groups
            # Note that this path uses a different combination of allowed IP groups
            if { (([class match -- [IP::client_addr] equals ipgrouptest]) or ([class match -- [IP::client_addr] equals ipgrouptest3])) } {
                # If the client IP matches either allowed group, do nothing and allow the request to proceed
                # The request continues through the normal processing flow
            } else {
                # If the client IP doesn't match any allowed group, block access
                # Return HTTP 403 Forbidden response and terminate request processing
                HTTP::respond 403
            }
        }
        # Implicit default case: any URI not matching the patterns above will be allowed
        # regardless of client IP address (no restrictions applied)
    }
}

# This is an LTM policy, not an iRule
ltm policy http.redirects {
    controls { forwarding }
    requires { http }
    rules {
        require_fqdn {
            actions {
                0 {
                    forward
                    reset
                }
            }
            conditions {
                0 {
                    http-host
                    host
                    not
                    values { my.domain.com }
                }
            }
            ordinal 1
        }
    }
    strategy all-match
}

# Create an F5 BIG-IP iRule that restricts website access to Internet Explorer browsers only. The rule should check if the User-Agent header contains "MSIE" and allow those requests to proceed normally, while blocking all other browsers by returning a custom message stating the browser isn't allowed.

when HTTP_REQUEST priority 500 {
    # Check if the User-Agent header contains "MSIE" (Internet Explorer)
    # If it does contain MSIE, return from the iRule and allow the request to proceed normally
    if { ([HTTP::header "User-Agent"] contains "MSIE") } {
        return
    }

    # If we reach this point, the User-Agent is not Internet Explorer
    # Block the request by sending a custom response with HTTP 200 status code
    # The response body informs the user that their browser type is not allowed
    HTTP::respond 200 content {your browser isn't allowed}
}

# Source: https://github.com/f5devcentral/irules-toolbox/blob/master/security/http/cookies/samesite-attributes.tcl
