# Create an F5 BIG-IP iRule that mitigates the POODLE vulnerability. It should check if the client's IP is in an allowed list, apply the appropriate SSL profile, and force SSL renegotiation to ensure the correct profile is used.

when CLIENT_ACCEPTED priority 500 {
    # Check if the client's IP address is in the "sslv3_allowed" class
    if { [class match -- [IP::client_addr] equals "sslv3_allowed"] } {
        # If the client is allowed to use SSLv3, set the SSL profile to allow it
        SSL::profile sslv3_enabled
        # Exit the rule early for allowed clients
        return
    }
    # For all other clients, use an SSL profile that disables SSLv3
    SSL::profile sslv3_disabled
}

when HTTP_REQUEST priority 500 {
    # Force an SSL renegotiation to apply the correct SSL profile
    SSL::renegotiate
}

# Create an F5 BIG-IP iRule that manages HTTP redirections based on connection security and requested path. The rule should track whether connections are using HTTPS, redirect root path requests to a specific application URL, allow secure connections to proceed normally, and redirect all other HTTP requests to their HTTPS equivalents.

when CLIENT_ACCEPTED priority 500 {
    # Initialize a flag to track whether this connection is using HTTPS/SSL
    # Default is 0 (false) - assuming HTTP until proven otherwise
    set https 0
}

when CLIENTSSL_HANDSHAKE priority 500 {
    # This event triggers when a client establishes an SSL/TLS connection
    # Update the https flag to 1 (true) to indicate this is a secure connection
    # This will be used later to determine if redirection is needed
    set https 1
}

when HTTP_REQUEST priority 500 {
    # Handle root path requests by redirecting to a specific application URL
    # This ensures users who visit the site root are sent to the main portal
    if {[HTTP::path] eq "/" } {
        HTTP::redirect "https://portal.mysite.org/eschool"
        return
    }

    # If this is already an HTTPS connection, no need for SSL redirection
    # Allow the request to continue processing normally
    if {$https} {
        return
    }

    # For all non-HTTPS requests that aren't to the root path,
    # Redirect to the same host and URI but using HTTPS protocol
    # getfield extracts the hostname without port number if present
    HTTP::redirect https://[getfield [HTTP::host] : 1][HTTP::uri]
}

# Create an F5 BIG-IP iRule that implements selective SSL offloading for specific paths. The rule check if the requested path matches entries in a data group configured for standard HTTP, and enable SSL only for paths not found in that data group.

when CLIENT_ACCEPTED priority 500 {
    # Initially disable SSL for all server-side connections
    # This makes all backend connections use HTTP by default
    SSL::disable serverside
}

when HTTP_REQUEST priority 500 {
    # Check if the requested path (converted to lowercase) matches any entries
    # in the "standard_http_dg" data group that are configured to use HTTP
    if { [class match -- [string tolower [HTTP::path]] starts_with standard_http_dg] } {
        # If the path matches, return without enabling SSL
        # These paths will continue using HTTP to the backend servers
        return
    }

    # For all paths not matching the standard_http_dg data group,
    # enable SSL for the server-side connection
    # This ensures these paths use HTTPS to the backend servers
    SSL::enable serverside
}

# Create an F5 BIG-IP iRule that implements selective SSL re-encryption based on the requested path. The rule should direct requests starting with "/main" to a beta pool with SSL re-encryption enabled, while routing all other requests to an alpha pool with SSL offloading (where the backend connection uses HTTP even though the client connection uses HTTPS).

when HTTP_REQUEST priority 500 {
    # Initialize the SSL flag to disabled (0) by default
    # This variable will determine if SSL re-encryption is needed for backend connections
    set usessl 0

    # Use a switch statement to match the requested path (converted to lowercase)
    # and select the appropriate server pool and SSL setting
    switch -glob -- [string tolower[HTTP::path]] {
        "/main*" {
            # For paths starting with "/main", use the beta pool
            # -glob allows wildcard matching with the asterisk
            pool beta__pool

            # Enable SSL re-encryption for these requests
            # by setting the usessl flag to 1
            set usessl 1
        }
        default {
            # For all other paths not matching above patterns
            # use the alpha pool as the default destination
            pool alpha_pool

            # Explicitly disable SSL re-encryption for these requests
            # (redundant since usessl is already 0, but makes intent clear)
            set usessl 0
        }
    }
}

when SERVER_CONNECTED priority 500 {
    # This event triggers after a connection to the backend server is established

    # Check if SSL re-encryption should be used
    # If usessl is 1 (meaning SSL is enabled), exit the event handler
    # and allow the default SSL behavior to continue
    if { $usessl == 1 } {
        return
    }

    # If we reach here, usessl is 0, meaning SSL should be disabled
    # Disable SSL for this server-side connection
    # This implements SSL offloading - client uses HTTPS but backend uses HTTP
    SSL::disable
}

# Create an F5 iRule that sorts different types of VPN traffic to appropriate pools. The iRule should identify and route Microsoft PPTP traffic (protocol 47 or TCP port 1723), IPSec traffic (protocols 50, 51, or UDP port 500), and L2TP traffic (protocol 115) to their respective dedicated pools, with any unmatched traffic falling through to the default pool.

when CLIENT_ACCEPTED priority 500 {
    # This event triggers as soon as a client connection is accepted
    # The iRule sorts different types of VPN traffic to appropriate pools

    if {[IP::protocol] == 47 || [TCP::local_port] == 1723} {
        # Route Microsoft PPTP VPN traffic to dedicated pool
        # Protocol 47 is GRE (Generic Routing Encapsulation) used for PPTP data tunnel
        # Port 1723 is the TCP control channel for PPTP connections
        pool ms_pptp
    } elseif {[IP::protocol] == 50 || [IP::protocol] == 51 || [UDP::local_port] == 500}  {
        # Route IPSec VPN traffic to dedicated pool
        # Protocol 50 is ESP (Encapsulating Security Payload) for encrypted IPSec data
        # Protocol 51 is AH (Authentication Header) for IPSec authentication
        # UDP port 500 is used by IKE (Internet Key Exchange) for IPSec key negotiation
        pool ipsec_pool
    } elseif {[IP::protocol] == 115} {
        # Route L2TP VPN traffic to dedicated pool
        # Protocol 115 is the L2TP (Layer 2 Tunneling Protocol)
        pool l2tp_pool
    }
    # If traffic doesn't match any VPN protocol, it will fall through
    # to the default pool configured on the virtual server
}

